describe('DUO 0x001D byte identity with v0.3.0', () => {
  test('every golden label and tape job hashes exactly as before the device table', () => {
    const now = goldenHashes();
    expect(Object.keys(now)).toEqual(Object.keys(BEFORE_DEVICE_TABLE));
    for (const [name, hash] of Object.entries(BEFORE_DEVICE_TABLE)) expect([name, now[name]]).toEqual([name, hash]);
  });

  test('building with the DUO table entry explicitly gives the same bytes', () => {
    expect(goldenHashes(DUO_128)).toEqual(BEFORE_DEVICE_TABLE);
  });

  test('findDevice(0x0922, 0x001d) is that entry, with the historical calibration', () => {
    expect(findDevice(0x0922, 0x001d)).toBe(DUO_128);
    expect(DUO_128.calibration).toBe(DEFAULT_CALIBRATION);
  });
});
